#include "estimate.h"
#include <QStringList>

int parseEstimate(const QString &text)
{
    const QStringList parts = text.split(' ', Qt::SkipEmptyParts);
    if (parts.isEmpty())
        return -1;
    int total = 0;
    for (const QString &part : parts) {
        if (part.size() < 2)
            return -1; // missing number
        const QString number = part.left(part.size() - 1);
        const QChar unit = part.back();
        bool ok = false;
        const int value = number.toInt(&ok);
        if (!ok || value < 0)
            return -1;
        switch (unit.unicode()) {
        case 'w': total += value * 5 * 8 * 60; break;
        case 'd': total += value * 8 * 60; break;
        case 'h': total += value * 60; break;
        case 'm': total += value; break;
        default: return -1;
        }
    }
    return total;
}

QString formatEstimate(int minutes)
{
    if (minutes < 0)
        return {};
    QStringList out;
    int rem = minutes;
    const int weeks = rem / (5 * 8 * 60);
    rem %= 5 * 8 * 60;
    if (weeks)
        out << QString::number(weeks) + "w";
    const int days = rem / (8 * 60);
    rem %= 8 * 60;
    if (days)
        out << QString::number(days) + "d";
    const int hours = rem / 60;
    rem %= 60;
    if (hours)
        out << QString::number(hours) + "h";
    if (rem > 0)
        out << QString::number(rem) + "m";
    else if (out.isEmpty())
        out << "0m";
    return out.join(' ');
}
